// Deterministic seeded PRNG (mulberry32) -- values baked as literals at authoring time,
// no runtime randomness ships in the composition.
function mulberry32(seed) {
  return function () {
    seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function genBar(seed, steps, min, max) {
  const rand = mulberry32(seed);
  const vals = [];
  let prev = min + (max - min) * 0.4;
  for (let i = 0; i < steps; i++) {
    // random walk with occasional larger jumps to feel "live"
    const jump = (rand() - 0.5) * (rand() < 0.3 ? 0.9 : 0.45);
    let v = prev + jump * (max - min);
    v = Math.max(min, Math.min(max, v));
    vals.push(Math.round(v * 100) / 100);
    prev = v;
  }
  return vals;
}

const DT = 0.14; // seconds per keyframe step
function stepsFor(duration) { return Math.ceil(duration / DT) + 2; }

